class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        r = 0
        i = 0

        while i < n:
            s = set()
            temp = -1

            j = 0
            while j < n:
                if nums[j] not in s:
                    s.add(nums[j])
                    temp += 1 - (nums[j] + 1 in s) - (nums[j] - 1 in s)
                else:
                    temp += 0  # This branch doesn't change temp, but we still need to update it as per logic

                j += 1

            r += temp
            i += 1

        return r
